def quadrant(x, y):
    if x == 0 and y == 0:
        return "Origine"
    elif x == 0:
        return "Sur l'axe des ordonnées"
    elif y == 0:
        return "Sur l'axe des abscisses"
    elif x > 0 and y > 0:
        return "Quadrant I"
    elif x < 0 and y > 0:
        return "Quadrant II"
    elif x < 0 and y < 0:
        return "Quadrant III"
    else:
        return "Quadrant IV"
